const job = $input.first().json;

const systemPrompt = `You are an expert IT recruiter assistant. Evaluate job postings for a Senior Software Engineer.

Target Profile: Senior/Lead/Architect, JS/TS/Node.js/React/PostgreSQL, Gdańsk OR remote.

Match if: Senior-level, Node.js/TS primary backend, Gdańsk or remote.
Reject if: Junior/Mid, primary backend Java/C#/.NET/PHP/Ruby/Go, not Gdańsk and not remote.
If Node.js + Java legacy both listed: match true ONLY if Node.js is listed first or described as primary.

Respond ONLY with valid JSON, no markdown:
{"match": true or false, "reason": "one sentence", "url": "job url"}`;

const userContent = [
  `Job Title: ${job.title}`,
  `Company: ${job.company}`,
  `Location: ${job.location || 'Not specified'}`,
  `Salary: ${job.salary || 'Not specified'}`,
  `URL: ${job.url}`,
  '',
  'Job Description:',
  job.body || 'No description available'
].join('\n');

return [{
  json: {
    ...job,
    ollamaBody: {
      model: 'llama3.1:latest',
      stream: false,
      keep_alive: 0,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userContent }
      ]
    }
  }
}];

const ollamaResp = $input.first().json;
const raw = ollamaResp?.message?.content || '';
const job = $('Code: Build Ollama Payload').first().json;

if (!raw) {
  console.log('[Evaluate] Empty Ollama response');
  return [];
}

let parsed;
try {
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  console.log(`[Evaluate] Parse error: ${raw.substring(0, 200)}`);
  return [];
}

if (typeof parsed.match !== 'boolean') {
  console.log(`[Evaluate] Bad shape: ${JSON.stringify(parsed)}`);
  return [];
}

console.log(`[Evaluate] ${parsed.match ? '✅ MATCH' : '❌ skip'} — ${parsed.reason}`);

return [{
  json: {
    id: job.id, title: job.title, company: job.company,
    url: job.url, source: job.source, location: job.location,
    salary: job.salary, tags: job.tags, scrapedAt: job.scrapedAt,
    match: parsed.match, reason: parsed.reason
  }
}];
